					<div v-else-if="activityError" class="rounded-2xl bg-ui-surface-red-50 p-4 text-sm text-ui-ink-red-600" role="alert">{{ activityError }}</div>
					<section v-else-if="activityDetail" class="rounded-2xl bg-ui-surface p-4 shadow-sm">
						<p class="text-xs font-semibold uppercase tracking-wide text-ui-ink-gray-500">Hasil kunjungan</p>
						<h2 class="mt-1 text-xl font-bold text-primary">{{ activityDetail.hasil || 'Hasil perlu dicek' }}</h2>
						<p class="mt-3 text-sm font-semibold text-ui-heading">{{ activityDetail.nama_nasabah || activityDetail.no_perjanjian || 'Nasabah belum terpetakan' }}</p>
						<p class="text-xs text-ui-ink-gray-500">{{ activityDetail.sumber }} · {{ activityDetail.no_perjanjian }}</p>
						<dl class="mt-4 grid grid-cols-2 gap-3 border-t border-ui-line pt-4 text-sm">
							<div><dt class="text-xs text-ui-ink-gray-500">Tanggal kunjungan</dt><dd class="mt-1 font-medium text-ui-heading">{{ formatDate(activityDetail.tanggal_kunjungan) }}</dd></div>
							<div><dt class="text-xs text-ui-ink-gray-500">PIC Collector</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.pic_collector || 'Belum terpetakan' }}</dd></div>
							<div v-if="activityDetail.bucket"><dt class="text-xs text-ui-ink-gray-500">Bucket</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.bucket }}</dd></div>
							<div v-if="activityDetail.angsuran_ke"><dt class="text-xs text-ui-ink-gray-500">Angsuran ke</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.angsuran_ke }}</dd></div>
							<div v-if="activityDetail.tanggal_janji_bayar"><dt class="text-xs text-ui-ink-gray-500">Tanggal janji bayar</dt><dd class="mt-1 font-medium text-ui-heading">{{ formatDate(activityDetail.tanggal_janji_bayar) }}</dd></div>
							<div v-if="activityDetail.tipe_pembayaran"><dt class="text-xs text-ui-ink-gray-500">Tipe pembayaran</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.tipe_pembayaran }}</dd></div>
							<div v-if="Number(activityDetail.nominal_bayar) > 0"><dt class="text-xs text-ui-ink-gray-500">Nominal bayar</dt><dd class="mt-1 font-medium text-ui-heading">{{ formatRupiah(activityDetail.nominal_bayar) }}</dd></div>
							<div v-if="activityDetail.nama_pic"><dt class="text-xs text-ui-ink-gray-500">PIC tarikan</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.nama_pic }}</dd></div>
							<div v-if="activityDetail.kategori"><dt class="text-xs text-ui-ink-gray-500">Kategori</dt><dd class="mt-1 font-medium text-ui-heading">{{ activityDetail.kategori }}</dd></div>
							<div v-if="activityDetail.tanggal_janji_tebus"><dt class="text-xs text-ui-ink-gray-500">Tanggal janji tebus</dt><dd class="mt-1 font-medium text-ui-heading">{{ formatDate(activityDetail.tanggal_janji_tebus) }}</dd></div>
							<div v-if="activityDetail.hasil === 'Tarik Unit'"><dt class="text-xs text-ui-ink-gray-500">Kunci</dt><dd class="mt-1 font-medium text-ui-heading">{{ Number(activityDetail.kunci) ? 'Ada' : 'Tidak ada' }}</dd></div>
							<div v-if="activityDetail.hasil === 'Tarik Unit'"><dt class="text-xs text-ui-ink-gray-500">STNK</dt><dd class="mt-1 font-medium text-ui-heading">{{ Number(activityDetail.stnk) ? 'Ada' : 'Tidak ada' }}</dd></div>
							<div v-if="activityDetail.keterangan_stnk" class="col-span-2"><dt class="text-xs text-ui-ink-gray-500">Keterangan STNK</dt><dd class="mt-1 whitespace-pre-wrap text-ui-heading">{{ activityDetail.keterangan_stnk }}</dd></div>
							<div v-for="field in detailTags" :key="field.label"><dt class="text-xs text-ui-ink-gray-500">{{ field.label }}</dt><dd class="mt-1 font-medium text-ui-heading">{{ field.value }}</dd></div>
						</dl>
						<div v-if="activityDetail.detail_case" class="mt-4 border-t border-ui-line pt-4"><p class="text-xs text-ui-ink-gray-500">Detail kasus</p><p class="mt-1 whitespace-pre-wrap text-sm text-ui-heading">{{ activityDetail.detail_case }}</p></div>
						<div v-if="activityPhotoUrl" class="mt-4 border-t border-ui-line pt-4"><p class="text-xs text-ui-ink-gray-500">Foto Kunjungan</p><button type="button" class="mt-1 inline-flex max-w-full items-center gap-1.5 text-left text-sm font-semibold text-primary hover:underline" @click="openImage(activityPhotoUrl, activityDetail.foto_kunjungan_nama || 'Foto Kunjungan')"><span class="truncate">{{ activityDetail.foto_kunjungan_nama || 'Lihat foto' }}</span><span aria-hidden="true">↗</span></button></div>
					</section>
				</template>
				<template v-else-if="!drillMetric">
					<form class="rounded-2xl bg-ui-surface p-4 shadow-sm" @submit.prevent="runFilters">
						<p class="mb-3 text-sm font-semibold text-ui-heading">Filter aktivitas</p>
						<div class="mb-3 flex flex-wrap gap-2">
							<button v-for="preset in presets" :key="preset.key" type="button" class="rounded-full px-3 py-2 text-xs font-semibold transition-colors" :class="activePreset === preset.key ? 'bg-primary text-white' : 'bg-ui-surface-gray-100 text-ui-ink-gray-600'" @click="setPreset(preset.key)">{{ preset.label }}</button>
						</div>
						<label class="mb-3 block text-xs font-medium text-ui-ink-gray-600">Rentang tanggal
							<PortalDateRangePicker class="mt-1" :from="filters.start_date" :to="filters.end_date" :min="String(context.start).slice(0, 10)" :max="String(context.end).slice(0, 10)" @change="setDateRange" />
						</label>
						<div class="grid grid-cols-2 gap-3">
							<label v-if="scope === 'team'" class="text-xs font-medium text-ui-ink-gray-600">PIC
								<SelectMenu v-model="filters.pic_collector" class="mt-1" :options="picOptions" placeholder="Semua PIC" clearable :btn-class="filterClass" />
							</label>
							<label v-if="scope === 'team'" class="text-xs font-medium text-ui-ink-gray-600">Bucket
								<SelectMenu v-model="filters.bucket" class="mt-1" :options="bucketOptions" placeholder="Semua bucket" clearable :btn-class="filterClass" />
							</label>
							<label class="col-span-2 text-xs font-medium text-ui-ink-gray-600">Sumber
								<SelectMenu v-model="filters.sumber" class="mt-1" :options="sourceOptions" placeholder="Semua sumber" clearable :btn-class="filterClass" />
							</label>
							<button type="submit" class="col-span-2 rounded-xl bg-primary px-3 py-3 text-sm font-semibold text-white" :disabled="loading">Terapkan filter</button>
						</div>
					</form>

					<p v-if="summary" class="text-xs text-ui-ink-gray-500">{{ formatDate(summary.start) }} – {{ formatDate(summary.end) }} · Diperbarui {{ formatTime(summary.updated_at) }}</p>
					<div v-if="summary" class="grid grid-cols-2 gap-2">
						<button v-for="card in cards" :key="card.metric" type="button" class="rounded-2xl bg-ui-surface p-4 text-left shadow-sm active:bg-ui-surface-gray-50" @click="openMetric(card.metric)"><p class="text-2xl font-bold text-primary">{{ card.count }}</p><p class="text-xs font-semibold text-ui-heading">{{ card.label }}</p><span v-if="card.daily" class="mt-2 inline-flex rounded-full px-2 py-0.5 text-[11px] font-semibold" :class="visitDailyDeltaTone(card.daily)">{{ visitDailyDeltaText(card.daily) }} vs kemarin</span><p v-if="card.hint" class="mt-1 text-xs text-ui-ink-gray-500">{{ card.hint }}</p></button>
					</div>

					<section v-if="summary?.series?.length" class="rounded-2xl bg-ui-surface p-4 shadow-sm"><h2 class="text-sm font-semibold text-ui-heading">Tren kunjungan</h2><p v-if="summary.series.length > 10" class="mt-1 text-xs text-ui-ink-gray-500">Geser ke bawah untuk melihat tanggal lainnya.</p><div class="mt-3 space-y-2" :class="summary.series.length > 10 ? 'scrollbar-hide max-h-80 overflow-y-auto pr-1' : ''"><div v-for="day in summary.series" :key="day.date" class="flex min-h-6 items-center gap-2 text-xs"><span class="w-16 shrink-0 text-ui-ink-gray-500">{{ shortDate(day.date) }}</span><div class="h-3 flex-1 rounded-full bg-ui-surface-gray-100"><div class="h-3 rounded-full bg-primary" :style="{ width: barWidth(day.total) }" /></div><span class="w-8 text-right font-semibold text-ui-heading">{{ day.total }}</span></div></div></section>

					<section v-if="scope === 'team'" class="rounded-2xl bg-ui-surface p-4 shadow-sm">
						<h2 class="text-sm font-semibold text-ui-heading">Per PIC</h2>
						<p class="mt-1 text-xs text-ui-ink-gray-500">Ketuk nama PIC atau jumlah kunjungan untuk melihat aktivitas.</p>
						<div v-if="picLoading && !picRows.length" class="py-4 text-sm text-ui-ink-gray-500">Memuat PIC...</div>
						<div v-else-if="!picRows.length && !error" class="py-4 text-sm text-ui-ink-gray-500">Tidak ada kunjungan pada filter ini.</div>
						<div v-for="row in picRows" :key="row.pic_collector" class="mt-3 rounded-xl border border-ui-line p-3">
							<div class="flex items-center justify-between gap-2">
								<button type="button" class="min-w-0 truncate text-left text-sm font-semibold text-ui-heading" @click="openMetric('visits', row.pic_collector)">{{ row.pic_collector }}</button>
								<div class="flex shrink-0 items-center gap-2 whitespace-nowrap text-xs"><span class="text-ui-ink-gray-500">{{ row.contracts }} nasabah</span><button type="button" class="font-bold text-primary" @click="openMetric('visits', row.pic_collector)">{{ row.total }} kunjungan →</button></div>
							</div>
							<p class="mt-1 text-xs text-ui-ink-gray-500">{{ row.promise }} janji · {{ row.payment }} Pembayaran Angsuran · {{ row.repossession }} tarik · {{ row.repeat_visit }} ulang</p>
						</div>
						<button v-if="picHasMore && !picExpanded" type="button" class="mt-3 w-full rounded-xl bg-ui-surface-gray-100 p-2 text-sm font-semibold text-primary" :disabled="picLoading" @click="loadAllPicRows">{{ picLoading ? 'Memuat...' : 'Tampilkan lebih banyak' }}</button>
						<button v-if="picExpanded" type="button" class="mt-3 w-full rounded-xl bg-ui-surface-gray-100 p-2 text-sm font-semibold text-primary" @click="collapsePicRows">Tampilkan lebih sedikit</button>
					</section>
				</template>

						<section v-else class="space-y-3"><p class="text-xs text-ui-ink-gray-500">{{ formatDate(filters.start_date) }} – {{ formatDate(filters.end_date) }}<span v-if="drillPic"> · {{ drillPic }}</span></p><div v-if="drillLoading && !drillRows.length" class="rounded-2xl bg-ui-surface p-5 text-center text-sm text-ui-ink-gray-500">Memuat aktivitas...</div><div v-else-if="!drillRows.length" class="rounded-2xl bg-ui-surface p-5 text-center text-sm text-ui-ink-gray-500">Tidak ada aktivitas.</div><div v-for="row in drillRows" :key="row.name || row.sumber + row.no_perjanjian" class="rounded-2xl bg-ui-surface p-4 shadow-sm"><div class="flex items-start justify-between gap-2"><div><p class="text-sm font-semibold text-ui-heading">{{ row.nama_nasabah || row.no_perjanjian || 'Nasabah belum terpetakan' }}</p><p class="text-xs text-ui-ink-gray-500">{{ row.sumber }} · {{ row.no_perjanjian }}</p></div><span class="text-xs font-semibold text-primary">{{ row.hasil || (drillMetric === 'contracts' ? row.visits + ' kunjungan' : 'Hasil perlu dicek') }}</span></div><p class="mt-2 text-xs text-ui-ink-gray-500"><span v-if="drillMetric === 'contracts'">Kunjungan terakhir: </span>{{ formatDate(row.tanggal_kunjungan || row.last_visit) }} · PIC {{ row.pic_collector || 'Belum terpetakan' }} · {{ row.bucket || 'Bucket kosong' }}</p><p v-if="row.creation" class="mt-1 text-xs text-ui-ink-gray-500">Dicatat {{ row.creation }}</p><button v-if="row.name" type="button" class="mt-3 inline-block text-sm font-semibold text-primary" @click="openActivity(row.name)">Buka detail kunjungan →</button></div><button v-if="drillHasMore" type="button" class="w-full rounded-xl bg-ui-surface p-3 text-sm font-semibold text-primary" :disabled="drillLoading" @click="loadDrill">{{ drillLoading ? 'Memuat...' : 'Muat lainnya' }}</button></section>
			</template>
		</main>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { call } from 'frappe-ui'
import SelectMenu from '../components/SelectMenu.vue'
import PortalDateRangePicker from '../components/PortalDateRangePicker.vue'
import { openImage } from '../composables/attachmentViewer'
import { visitDailyDeltaText, visitDailyDeltaTone } from '../composables/visitDailyComparison'

const props = defineProps({ scope: { type: String, default: 'team' } })
const scope = computed(() => props.scope)
const API = 'juragan.api.portal.visit_collection.'
const context = ref(null)
const summary = ref(null)
const filters = reactive({ start_date: '', end_date: '', pic_collector: '', bucket: '', sumber: '' })
const loading = ref(false)
const error = ref('')
const picRows = ref([])
const allPicRows = ref(null)
const picExpanded = ref(false)
const picHasMore = ref(false)
const picOffset = ref(0)
const picLoading = ref(false)
const selectedActivityName = ref('')
const activityDetail = ref(null)
const activityLoading = ref(false)
const activityError = ref('')
const drillMetric = ref('')
const drillPic = ref('')
const drillRows = ref([])
const drillHasMore = ref(false)
const drillOffset = ref(0)
const drillLoading = ref(false)
const filterClass = 'rounded-xl border border-ui-line-gray-300 bg-ui-surface px-3 py-2.5 text-sm text-ui-heading'
const sourceOptions = [{ value: 'KSP', label: 'KSP' }, { value: 'JG', label: 'JG' }]
const presets = [{ key: 'today', label: 'Hari ini' }, { key: 'last7', label: '7 hari' }, { key: 'month', label: 'Bulan ini' }]
const activePreset = ref('today')
const picOptions = computed(() => (context.value?.pics || []).map((pic) => ({ value: pic, label: pic === '__UNMAPPED__' ? 'Belum terpetakan' : pic })))
const bucketOptions = computed(() => context.value?.buckets || [])
let filterVersion = 0
let activityVersion = 0

const labels = { visits: 'Jumlah kunjungan', contracts: 'Nasabah dikunjungi', promise: 'Janji Bayar', payment: 'Pembayaran Angsuran', repossession: 'Tarik Unit', repeat: 'Kunjungan Ulang', incomplete: 'Hasil perlu dicek' }
const drillTitle = computed(() => labels[drillMetric.value] || 'Rincian aktivitas')
const cards = computed(() => summary.value ? [
	{ metric: 'visits', label: labels.visits, count: summary.value.total },
	{ metric: 'contracts', label: labels.contracts, count: summary.value.contracts },
	{ metric: 'promise', label: labels.promise, count: summary.value.results?.['Janji Bayar'] || 0 },
	{ metric: 'payment', label: labels.payment, count: summary.value.results?.['Pembayaran Angsuran'] || 0 },
	{ metric: 'repossession', label: labels.repossession, count: summary.value.results?.['Tarik Unit'] || 0 },
	{ metric: 'repeat', label: labels.repeat, count: summary.value.results?.['Kunjungan Ulang'] || 0 },
	...(Number(summary.value.incomplete) > 0 ? [{ metric: 'incomplete', label: labels.incomplete, count: summary.value.incomplete, hint: 'Hasil kosong atau di luar empat pilihan' }] : []),
].map((card) => ({ ...card, daily: card.metric === 'visits' ? summary.value.daily_comparison?.metrics?.visits : null })) : [])
const detailTags = computed(() => activityDetail.value ? [
	{ label: 'Status nasabah', value: activityDetail.value.status_nasabah },
	{ label: 'Kategori kasus', value: activityDetail.value.case_category },
	{ label: 'Tindakan', value: activityDetail.value.action },
].filter((field) => field.value) : [])
const activityPhotoUrl = computed(() => activityDetail.value?.foto_kunjungan && activityDetail.value?.name
	? `/api/method/${API}get_team_visit_photo?name=${encodeURIComponent(activityDetail.value.name)}&scope=${scope.value}`
	: '')
const maxDaily = computed(() => Math.max(1, ...(summary.value?.series || []).map((row) => Number(row.total) || 0)))
function barWidth(value) { return Math.max(0, Math.round(((Number(value) || 0) / maxDaily.value) * 100)) + '%' }
function formatDate(value) { if (!value) return '—'; const d = new Date(String(value).slice(0, 10) + 'T00:00:00'); return Number.isNaN(d.getTime()) ? String(value) : new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(d) }
function shortDate(value) { if (!value) return '—'; return String(value).slice(8, 10) + '/' + String(value).slice(5, 7) }
function formatRupiah(value) { return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value) || 0) }
function formatTime(value) { return value ? String(value).slice(11, 16) : '—' }
function iso(date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
function setPreset(preset) {
	if (!context.value?.period_available) return
	const end = String(context.value.end).slice(0, 10)
	const start = String(context.value.start).slice(0, 10)
	filters.end_date = end
	if (preset === 'month') filters.start_date = start
	else if (preset === 'last7') {
		const date = new Date(end + 'T00:00:00')
		date.setDate(date.getDate() - 6)
		filters.start_date = iso(date) < start ? start : iso(date)
	} else filters.start_date = end
	activePreset.value = preset
}
function setDateRange(range) { filters.start_date = range.from; filters.end_date = range.to; activePreset.value = '' }
function args() { return { scope: scope.value, start_date: filters.start_date, end_date: filters.end_date, ...(scope.value === 'team' ? { pic_collector: filters.pic_collector, bucket: filters.bucket } : {}), sumber: filters.sumber } }
async function loadPicRows(version = filterVersion, selectedFilters = args()) {
	if (picLoading.value) return
	picLoading.value = true
	try { const data = await call(API + 'get_team_visit_pic_rows', { ...selectedFilters, limit: 6, offset: picOffset.value }); if (version !== filterVersion) return; picRows.value.push(...(data.rows || [])); picHasMore.value = !!data.has_more; picOffset.value = data.next_offset || picRows.value.length }
	catch (e) { if (version === filterVersion) error.value = e?.messages?.[0] || e?.message || 'Gagal memuat PIC.' }
	finally { if (version === filterVersion) picLoading.value = false }
}
async function loadAllPicRows() {
	if (picLoading.value || !picHasMore.value) return
	if (allPicRows.value) { picRows.value = allPicRows.value; picExpanded.value = true; picHasMore.value = false; return }
	const version = filterVersion
	const selectedFilters = args()
	const rows = [...picRows.value]
	let offset = picOffset.value
	picLoading.value = true
	error.value = ''
	try {
		let hasMore = true
		while (hasMore) {
			const data = await call(API + 'get_team_visit_pic_rows', { ...selectedFilters, limit: 50, offset })
			if (version !== filterVersion) return
			if (!data.rows?.length) throw new Error('Daftar PIC tidak dapat dimuat lengkap.')
			rows.push(...data.rows)
			hasMore = !!data.has_more
			offset = data.next_offset ?? rows.length
		}
		allPicRows.value = rows
		picRows.value = rows
		picExpanded.value = true
		picHasMore.value = false
	} catch (e) { if (version === filterVersion) error.value = e?.messages?.[0] || e?.message || 'Gagal memuat PIC.' }
	finally { if (version === filterVersion) picLoading.value = false }
}
function collapsePicRows() { picRows.value = (allPicRows.value || picRows.value).slice(0, 6); picExpanded.value = false; picHasMore.value = !!allPicRows.value && allPicRows.value.length > 6 }
async function runFilters() {
	const version = ++filterVersion
	const selectedFilters = args()
	loading.value = true; error.value = ''; summary.value = null; picRows.value = []; allPicRows.value = null; picExpanded.value = false; picOffset.value = 0; picHasMore.value = false; picLoading.value = false
	try { const [data] = await Promise.all([call(API + 'get_team_visit_summary', selectedFilters), ...(scope.value === 'team' ? [loadPicRows(version, selectedFilters)] : [])]); if (version === filterVersion) summary.value = data }
	catch (e) { if (version === filterVersion) error.value = e?.messages?.[0] || e?.message || 'Gagal memuat dashboard.' }
	finally { if (version === filterVersion) loading.value = false }
}
async function loadDrill() {
	if (drillLoading.value) return
	drillLoading.value = true; error.value = ''
	try { const data = await call(API + 'get_team_visit_drilldown', { ...args(), ...(scope.value === 'team' ? { pic_collector: drillPic.value === 'Belum terpetakan' ? '__UNMAPPED__' : (drillPic.value || filters.pic_collector) } : {}), metric: drillMetric.value, limit: 20, offset: drillOffset.value }); drillRows.value.push(...(data.rows || [])); drillHasMore.value = !!data.has_more; drillOffset.value = data.next_offset || drillRows.value.length }
	catch (e) { error.value = e?.messages?.[0] || e?.message || 'Gagal memuat aktivitas.' }
	finally { drillLoading.value = false }
}
async function openActivity(name) {
	const version = ++activityVersion
	selectedActivityName.value = name
	activityDetail.value = null
	activityError.value = ''
	activityLoading.value = true
	error.value = ''
	try { const detail = await call(API + 'get_team_visit_activity', { name, scope: scope.value }); if (version === activityVersion) activityDetail.value = detail }
	catch (e) { if (version === activityVersion) activityError.value = e?.messages?.[0] || e?.message || 'Gagal memuat detail kunjungan.' }
	finally { if (version === activityVersion) activityLoading.value = false }
}
function closeActivity() { activityVersion++; selectedActivityName.value = ''; activityDetail.value = null; activityError.value = ''; activityLoading.value = false }
function openMetric(metric, pic = '') { drillMetric.value = metric; drillPic.value = pic; drillRows.value = []; drillOffset.value = 0; drillHasMore.value = false; loadDrill() }
function closeDrill() { drillMetric.value = ''; drillPic.value = ''; drillRows.value = []; error.value = '' }
async function refresh() {
	if (selectedActivityName.value) { await openActivity(selectedActivityName.value); return }
	if (drillMetric.value) { drillRows.value = []; drillOffset.value = 0; await loadDrill(); return }
	loading.value = true; error.value = ''
	try { if (!context.value) { context.value = await call(API + 'get_team_visit_context', { scope: scope.value }); if (context.value?.period_available) setPreset(scope.value === 'self' ? 'month' : 'today') } if (context.value?.period_available) await runFilters() }
	catch (e) { error.value = e?.messages?.[0] || e?.message || 'Gagal memuat dashboard.' }
	finally { loading.value = false }
}
onMounted(refresh)
</script>
