<template>
	<button type="button" class="flex w-full items-center justify-between gap-2 rounded-xl border border-ui-line-gray-300 bg-ui-surface px-3 py-2.5 text-left text-sm text-ui-heading" @click="openPicker">
		<span class="min-w-0 truncate">{{ formatDate(from) }} – {{ formatDate(to) }}</span>
		<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4 shrink-0 text-ui-ink-gray-400"><path d="M8 2v4" /><path d="M16 2v4" /><rect width="18" height="18" x="3" y="4" rx="2" /><path d="M3 10h18" /></svg>
	</button>

	<Teleport to="body">
		<Transition enter-active-class="transition-opacity duration-200" enter-from-class="opacity-0" leave-active-class="transition-opacity duration-150" leave-to-class="opacity-0">
			<div v-if="open" class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40" @click.self="open = false">
				<Transition appear enter-active-class="transition-transform duration-200 ease-out" enter-from-class="translate-y-full" leave-active-class="transition-transform duration-150 ease-in" leave-to-class="translate-y-full">
					<div v-if="open" class="max-h-[85dvh] w-full max-w-screen-sm overflow-y-auto rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl">
						<div class="mx-auto mb-3 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
						<h2 class="text-center text-base font-semibold text-ui-heading">Pilih rentang tanggal</h2>
						<p class="mt-1 text-center text-xs text-ui-ink-gray-500">{{ monthLabel }} · periode Live</p>
						<div class="mt-4 grid grid-cols-7 text-center text-xs font-semibold text-ui-ink-gray-400"><span v-for="day in weekdays" :key="day" class="py-2">{{ day }}</span></div>
						<div class="grid grid-cols-7 gap-y-1">
							<div v-for="(day, index) in days" :key="index" class="flex justify-center py-0.5">
								<button v-if="day" type="button" class="flex h-10 w-10 items-center justify-center rounded-full text-sm transition-colors disabled:text-ui-ink-gray-300" :class="dayClass(day)" :disabled="day < minDate || day > maxDate" @click="pick(day)">{{ Number(day.slice(8, 10)) }}</button>
							</div>
						</div>
						<p class="mt-4 rounded-xl bg-ui-surface-gray-50 px-3 py-2.5 text-sm text-ui-ink-gray-600">{{ draftFrom ? formatDate(draftFrom) : 'Pilih tanggal mulai' }} {{ draftTo ? '– ' + formatDate(draftTo) : '· pilih tanggal akhir' }}</p>
						<div class="mt-4 grid grid-cols-2 gap-2"><button type="button" class="rounded-full border border-ui-line-gray-300 py-3 text-sm font-semibold text-ui-ink-gray-700" @click="open = false">Batal</button><button type="button" class="rounded-full bg-primary py-3 text-sm font-semibold text-white disabled:opacity-40" :disabled="!draftFrom || !draftTo" @click="apply">Gunakan tanggal</button></div>
					</div>
				</Transition>
			</div>
		</Transition>
	</Teleport>
</template>

<script setup>
import { computed, ref } from 'vue'

const props = defineProps({
	from: { type: String, default: '' },
	to: { type: String, default: '' },
	min: { type: String, required: true },
	max: { type: String, required: true },
})
const emit = defineEmits(['change'])
const weekdays = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const open = ref(false)
const draftFrom = ref('')
const draftTo = ref('')
const selectingNewRange = ref(false)
const minDate = computed(() => String(props.min).slice(0, 10))
const maxDate = computed(() => String(props.max).slice(0, 10))
const monthLabel = computed(() => new Intl.DateTimeFormat('id-ID', { month: 'long', year: 'numeric' }).format(new Date(minDate.value + 'T00:00:00')))
const days = computed(() => {
	const [year, month] = minDate.value.split('-').map(Number)
	const first = new Date(year, month - 1, 1)
	const offset = (first.getDay() + 6) % 7
	const count = new Date(year, month, 0).getDate()
	return [...Array(offset).fill(null), ...Array.from({ length: count }, (_, i) => `${year}-${String(month).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`)]
})
function formatDate(value) {
	if (!value) return '—'
	return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(String(value).slice(0, 10) + 'T00:00:00'))
}
function dayClass(day) {
	if (day === draftFrom.value || day === draftTo.value) return 'bg-primary font-semibold text-white'
	if (draftFrom.value && draftTo.value && day > draftFrom.value && day < draftTo.value) return 'bg-ui-surface-blue-50 text-primary'
	return 'text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function openPicker() {
	draftFrom.value = String(props.from || '').slice(0, 10)
	draftTo.value = String(props.to || '').slice(0, 10)
	selectingNewRange.value = false
	open.value = true
}
function pick(day) {
	if (!selectingNewRange.value || day < draftFrom.value) {
		draftFrom.value = day
		draftTo.value = ''
		selectingNewRange.value = true
	} else {
		draftTo.value = day
		selectingNewRange.value = false
	}
}
function apply() {
	emit('change', { from: draftFrom.value, to: draftTo.value })
	open.value = false
}
</script>
